-- 0001_identity: tables of the identity module (delivery 1; docs/modules/identity.md, ADR-0027). Generated by
-- `pnpm db:generate --name=identity`; the audit_log guard at the end is hand-written (ADR-0024 #2). Reference rows
-- (permissions, system roles, the TRANSIT warehouse) are synced by the api at boot, not here. Applied migrations
-- are never edited.

CREATE TABLE "audit_log" (
	"id" bigint PRIMARY KEY GENERATED ALWAYS AS IDENTITY (sequence name "audit_log_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"occurred_at" timestamp with time zone DEFAULT now() NOT NULL,
	"actor_kind" text NOT NULL,
	"actor_id" bigint,
	"actor_label" text,
	"action" text NOT NULL,
	"entity" text NOT NULL,
	"entity_id" text NOT NULL,
	"before" jsonb,
	"after" jsonb,
	"request_id" text,
	CONSTRAINT "audit_log_actor_kind" CHECK ("audit_log"."actor_kind" IN ('STAFF', 'CUSTOMER', 'SYSTEM')),
	CONSTRAINT "audit_log_actor" CHECK (("audit_log"."actor_kind" = 'SYSTEM' AND "audit_log"."actor_id" IS NULL)
        OR ("audit_log"."actor_kind" <> 'SYSTEM' AND "audit_log"."actor_id" IS NOT NULL))
);
--> statement-breakpoint
CREATE TABLE "auth_sessions" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"user_id" bigint NOT NULL,
	"token_hash" text NOT NULL,
	"previous_token_hash" text,
	"rotated_at" timestamp with time zone,
	"user_agent" text,
	"ip" "inet",
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"last_used_at" timestamp with time zone DEFAULT now() NOT NULL,
	"expires_at" timestamp with time zone NOT NULL,
	"revoked_at" timestamp with time zone,
	"revoked_reason" text,
	CONSTRAINT "auth_sessions_revoked_reason" CHECK (("auth_sessions"."revoked_at" IS NULL) = ("auth_sessions"."revoked_reason" IS NULL)
        AND ("auth_sessions"."revoked_reason" IS NULL OR "auth_sessions"."revoked_reason" IN
          ('LOGOUT', 'LOGOUT_ALL', 'ADMIN', 'PASSWORD_CHANGED', 'USER_DISABLED', 'TOKEN_REUSE'))),
	CONSTRAINT "auth_sessions_expiry" CHECK ("auth_sessions"."expires_at" > "auth_sessions"."created_at")
);
