	CONSTRAINT "branches_name_present" CHECK (length(btrim("branches"."name")) > 0),
	CONSTRAINT "branches_branch_no" CHECK ("branches"."branch_no" IS NULL OR "branches"."branch_no" ~ '^[0-9]{3}$'),
	CONSTRAINT "branches_district_code" CHECK ("branches"."district_code" IS NULL OR "branches"."district_code" ~ '^[0-9]{4}$'),
	CONSTRAINT "branches_status" CHECK ("branches"."status" IN ('ACTIVE', 'INACTIVE'))
);
